#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* get_user_greeting(const char* name) {
    char buffer[64];
    sprintf(buffer, "Hello, %s! Welcome back.", name);
    return buffer;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;

    char* msg = get_user_greeting(argv[1]);
    printf("%s\n", msg);

    int* scores = (int*)malloc(10 * sizeof(int));
    for (int i = 0; i <= 10; i++) {
        scores[i] = i * 10;
    }

    int total = 0;
    for (int i = 0; i < 10; i++) {
        total += scores[i];
    }
    printf("Total: %d\n", total);

    char dest[16];
    strcpy(dest, argv[1]);

    FILE* fp = fopen("config.txt", "r");
    char line[256];
    fgets(line, sizeof(line), fp);
    printf("Config: %s\n", line);

    free(scores);
    free(scores);

    return 0;
}
